async function* readArchive(chunks) {
  let iterator;
  let sourceDone = false;
  let failed = false;

  try {
    iterator = chunks[Symbol.asyncIterator]();

    const decoder = new TextDecoder();
    let buffer = "";
    let line = "";
    let lineNumber = 1;
    let decoderFlushed = false;

    for (;;) {
      let yielded = false;
      let position = 0;

      while (position < buffer.length) {
        const newline = buffer.indexOf("\n", position);

        if (newline === -1) {
          line += buffer.slice(position);
          position = buffer.length;
          break;
        }

        line += buffer.slice(position, newline);
        position = newline + 1;

        if (line.endsWith("\r")) {
          line = line.slice(0, -1);
        }

        const currentLine = line;
        const currentLineNumber = lineNumber++;
        line = "";

        if (currentLine.trim() === "") {
          continue;
        }

        let value;
        try {
          value = JSON.parse(currentLine);
        } catch (error) {
          error.code = "INVALID_RECORD";
          error.line = currentLineNumber;
          throw error;
        }

        buffer = buffer.slice(position);
        yielded = true;
        yield value;
        break;
      }

      if (yielded) {
        continue;
      }

      buffer = "";

      if (sourceDone) {
        if (!decoderFlushed) {
          decoderFlushed = true;
          buffer = decoder.decode();
          continue;
        }

        if (line.length > 0) {
          const currentLine = line;
          const currentLineNumber = lineNumber++;

          if (currentLine.trim() !== "") {
            try {
              yield JSON.parse(currentLine);
            } catch (error) {
              error.code = "INVALID_RECORD";
              error.line = currentLineNumber;
              throw error;
            }
          }
        }

        return;
      }

      const result = await iterator.next();

      if (result.done) {
        sourceDone = true;
      } else {
        buffer = decoder.decode(result.value, { stream: true });
      }
    }
  } catch (error) {
    failed = true;
    throw error;
  } finally {
    if (iterator && !sourceDone && typeof iterator.return === "function") {
      if (failed) {
        try {
          await iterator.return();
        } catch (_) {}
      } else {
        await iterator.return();
      }
    }
  }
}
